def factorial(x):
    result = 1
    for i in range(1, x+1):
        result = result * i
    return int(result)

def square_calcs(x):
    total_moves = 2 * x
    total_possibilities = factorial(total_moves)
    rights = factorial(x)
    downs = rights
    return int(total_possibilities / rights / downs)

def main_solution(grid_size):
    return square_calcs(grid_size)

def main_solution(A, target):
    if len(A) <= 1:
        return 0
    minnum = min(A)
    maxnum = max(A)
    adjusted_A = [x - minnum for x in A]
    max_val = max(adjusted_A)
    n = len(adjusted_A)
    dp = [[0] * (max_val + 1) for _ in range(n)]

    for i in range(n):
        for k in range(max_val + 1):
            if i == 0:
                dp[i][k] = abs(adjusted_A[i] - k)
            else:
                min_predp = max(0, k - target)
                max_predp = min(max_val, k + target)
                min_prev = min(dp[i-1][min_predp : max_predp + 1])
                dp[i][k] = min_prev + abs(adjusted_A[i] - k)

    return min(dp[-1])

