def main_solution(operations):
    # Process a list of operations to manage a key-value map
    # Initialize an empty dictionary to simulate XMap behavior
    xm = {}
    for op in operations:
        action = op['action']
        key = op['key']
        if action == 'add':
            xm[key] = op['value']
        elif action == 'delete':
            if key in xm:
                del xm[key]
        elif action == 'modify':
            if key in xm:
                xm[key] = op['value']
    return xm

