def main_solution(test_cases):
    results = []
    for case in test_cases:
        sorted_case = sorted(case)
        has_prefix = False
        for i in range(1, len(sorted_case)):
            prev = sorted_case[i-1]
            curr = sorted_case[i]
            if prev == curr[:len(prev)]:
                has_prefix = True
                break
        results.append("NO" if has_prefix else "YES")
    return results
